#include "SolarSystemController.h"
#include <QTimer>
#include <QTimeZone>
SolarSystemController::SolarSystemController(QObject*p):QObject(p){connect(&m_clock,&SimulationClock::changed,this,&SolarSystemController::refresh);refresh();}
void SolarSystemController::refresh(){auto dt=m_clock.dateTime();m_sun.update(SolarCalculator::calculate(dt,m_lat,m_lon));auto ev=SolarCalculator::events(dt.date(),m_lat,m_lon,dt.timeZone());m_sunrise=ev.sunrise?ev.sunrise->toString("HH:mm"):"Indisponible";m_sunset=ev.sunset?ev.sunset->toString("HH:mm"):"Indisponible";emit changed();}
void SolarSystemController::tick(){m_clock.tick(1000);} void SolarSystemController::setLatitude(double v){if(v>=-90&&v<=90){m_lat=v;refresh();}} void SolarSystemController::setLongitude(double v){if(v>=-180&&v<=180){m_lon=v;refresh();}} void SolarSystemController::setSpeed(double v){m_clock.setSpeed(v);} void SolarSystemController::pauseResume(){m_clock.running()?m_clock.pause():m_clock.resume();} void SolarSystemController::advance(int n){m_clock.advanceMinutes(n);} void SolarSystemController::setDateTime(QDateTime v){m_clock.setDateTime(v);} void SolarSystemController::setMinuteOfDay(int n){auto d=m_clock.dateTime();m_clock.setDateTime(QDateTime(d.date(),QTime(0,0).addSecs(qBound(0,n,1439)*60),d.timeZone()));} void SolarSystemController::realTime(){m_clock.setDateTime(QDateTime::currentDateTime());m_clock.resume();} void SolarSystemController::sunriseTime(){auto e=SolarCalculator::events(m_clock.dateTime().date(),m_lat,m_lon,m_clock.dateTime().timeZone());if(e.sunrise)setMinuteOfDay(e.sunrise->hour()*60+e.sunrise->minute());} void SolarSystemController::solarNoon(){setMinuteOfDay(720-(int)qRound(m_lon/15.0*60));} void SolarSystemController::sunsetTime(){auto e=SolarCalculator::events(m_clock.dateTime().date(),m_lat,m_lon,m_clock.dateTime().timeZone());if(e.sunset)setMinuteOfDay(e.sunset->hour()*60+e.sunset->minute());}
